 var ranges;
 let seed = Math.random() * 134;
 var mySize, margin;
 let str_wei = 0;

 // colors
 let colors0 = "281914-1a1a1a-202020-242e30".split("-").map((a) => "#" + a);
 let colors1 = "fef9fb-fafdff-ffffff-fcfbf4-f9f8f6".split("-").map((a) => "#" + a);
 let colors2 = "8c75ff-c553d2-2dfd60-2788f5-23054f-f21252-8834f1-c4dd92-184fd3-f9fee2-2E294E-541388-F1E9DA-FFD400-D90368-e9baaa-ffa07a-164555-ffe1d0-acd9e7-4596c7-6d8370-e45240-21d3a4-3303f9-cd2220-173df6-244ca8-a00360-b31016".split("-").map((a) => "#" + a);
 // let colors2 = "51608C-6A8AA6-BFCDD9-BF8756-8C512E-635C73-272B40-F2DAAC-D99E6A-D97E6A-D7D7D9-038C33-ACF216-698C1C-97BF04-192E40-326A8C-3B758C-7AACBF-C4EAF2-d625d9-5d29a6-1d2a73-1771bf-a0d3f2-024059-A0A603-D98E04-A67F5D-D9C9BA-2450A6-639CBF-F2EFBD-F28705-F2380F-381A40-90BF2A-F2CB05-BF751B-F24F13".split("-").map((a) => "#" + a);
 let colors_cyber = "ee0cf2-352ef2-1df252-f2e41d".split("-").map((a) => "#" + a);
 let color1, color2;
 let colorselet = [];

let pastel_bg = "ccd4bf-e7cba9-eebab2-f5f3f7-f5e2e4-f4c815-f9cad7-A57283-c1d5de-deede6-AAD9CD-E8D595-E9BBB5-E7CBA9-8DA47E-f7f6cf-b6d8f2-f4cfdf-9ac8eb".split("-").map((a) => "#" + a); //Mini Pastel Pops


 let unit;
 let count;
 let Cubes = [];
 let canvasW;
 let canvasH;

 function setup() {
	 canvasW = windowWidth;
 		canvasH = windowHeight;
 	// pixelDensity(5);
 	randomSeed(seed);
 	mySize = min(canvasW, canvasH);
 	// mySize = 1000;
 	margin = mySize / 100;
  createCanvas(canvasW, canvasH);
 	colorselet[0] = random(colors1);
 	colorselet[1] = random(colors2);
 	colorselet[2] = random(pastel_bg);
 	colorselet[3] = random(pastel_bg);
 	colorselet[4] = random(pastel_bg);
 	// colorselet[5] = random(colors2);
 	// colorselet[6] = random(pastel_bg);
 	// colorselet[7] = random(pastel_bg);
 	unit = int(random(20, 30));

 	noStroke();
 	let wideCount = width / unit;
 	let highCount = height / unit;
 	count = wideCount * highCount;

 	let index = 0;
 	for (let y = 0; y < highCount; y++) {
 		for (let x = 0; x < wideCount; x++) {
 			Cubes[index++] = new Brush(
 				x * unit,
 				y * unit,
 				random(unit),
 				random(unit),
 				random(2, 0.5),
 				6 * unit / random(0.5, 2)
 			);
 		}
 	}
 	let filter1 = new makeFilter();
 	background(random(colors1));
 }

 function draw() {
 	randomSeed(seed);
	 translate(canvasW/2,canvasH/2)
	 rotate(PI/-2)
	 translate(-canvasW/2,-canvasH/2)
 	for (let i = 0; i < count; i++) {
 		Cubes[i].update();
 		Cubes[i].draw();
 	}
 }

 class Brush {
 	constructor(xOff, yOff, x, y, speed, unit) {
 		this.xOff = xOff * 2;
 		this.yOff = yOff * 2;
 		this.x = x;
 		this.y = y;
 		this.speed = speed * 2;
 		this.unit = unit;
 		this.xDir = 1;
 		this.yDir = 1;
 	}

 	update() {
		// 對角線移動的更新
    this.x += this.speed * this.xDir;
    this.y += this.speed * this.yDir;  // 確保y座標的移動與x座標相同

    // 檢查x座標是否超出範圍
    if (this.x >= this.unit || this.x <= 0) {
        this.xDir *= -1;  // 改變x方向
        this.yDir *= -1;  // 同時改變y方向，保持對角線方向
    }

    // 檢查y座標是否超出範圍（通常不需要，因為y的變化與x保持同步）
    if (this.y >= this.unit || this.y <= 0) {
        this.yDir *= -1;  // 改變y方向
        this.xDir *= -1;  // 同時改變x方向，保持對角線方向
    }



 		// this.x = this.x + this.speed * this.xDir;
 		// if (this.x >= this.unit || this.x <= 0) {
 		// 	this.xDir *= -1;
 		// 	this.x = this.x + 1 * this.xDir;
 		// 	this.y = this.y + 1 * this.yDir;
 		// }
 		// if (this.y >= this.unit || this.y <= 0) {
 		// 	this.yDir *= -1;
 		// 	this.y = this.y + 1 * this.yDir;
 		// }
 	}

 	draw() {
 		noStroke();
 		fill(str(random(colorselet)));
 		let y_size = random(30) * noise(sin(this.x), cos(this.y), frameCount * 0.01);
 		rect(this.xOff + this.x, this.yOff + this.y, 10 * random(random(random())), y_size);
 	}
 }

 function makeFilter() {
 	randomSeed(seed);
 	// noiseのフィルターをつくる
 	colorMode(HSB, 360, 100, 100, 100);
 	drawingContext.shadowColor = color(0, 0, 5, 5);
 	overAllTexture = createGraphics(width, height);
 	overAllTexture.loadPixels();
 	for (var i = 0; i < width; i++) {  // noprotect
 		for (var j = 0; j < height; j++) { // noprotect
 			overAllTexture.set(
 				i,
 				j,
 				color(0, 10, 70, noise(i / 3, j / 3, (i * j) / 50) * random(10, 25))
 			);
 		}
 	}
 	overAllTexture.updatePixels();
 }

